#include <bits/stdc++.h>
#include <omp.h>
using namespace std;struct L{int a,b,c;bool operator==(L const&o)const{return a==o.a&&b==o.b&&c==o.c;}};struct H{size_t operator()(L const&x)const noexcept{return ((uint64_t)(x.a+100)<<42)^((uint64_t)(x.b+100)<<32)^(uint32_t)(x.c+100000);}};vector<int>pl;int C3[61],K[1771];L ca(int x1,int y1,int x2,int y2){int A=y2-y1,B=x1-x2,C=A*x1+B*y1,g=gcd(abs(A),gcd(abs(B),abs(C)));if(g)A/=g,B/=g,C/=g;if(A<0||(A==0&&B<0))A=-A,B=-B,C=-C;return{A,B,C};}void init(){unordered_map<L,int,H>m;m.reserve(240000);pl.assign(810000,-1);int z=0;for(int u=0;u<900;u++)for(int v=u+1;v<900;v++){auto q=ca(u/30,u%30,v/30,v%30);auto[it,n]=m.emplace(q,z);if(n)z++;pl[u*900+v]=pl[v*900+u]=it->second;}for(int k=0;k<=60;k++)C3[k]=k*(k-1)*(k-2)/6,K[k*(k-1)/2]=k;cerr<<"lines="<<z<<"\n";}
struct W{vector<unsigned short>base,add;vector<int>mark,touch,bt;int stamp=1,bp=0;vector<int>fixed;W(int n):base(n),add(n),mark(n){touch.reserve(900);bt.reserve(1300);}void prep(vector<int>const&f){for(int id:bt)base[id]=0;bt.clear();fixed=f;for(int i=0;i<(int)f.size();i++)for(int j=i+1;j<(int)f.size();j++){int id=pl[f[i]*900+f[j]];if(base[id]++==0)bt.push_back(id);}bp=0;for(int id:bt)bp+=C3[K[base[id]]];}int pot(vector<int>const&m){if(++stamp==INT_MAX){fill(mark.begin(),mark.end(),0);stamp=1;}touch.clear();auto inc=[&](int id){if(mark[id]!=stamp){mark[id]=stamp;add[id]=0;touch.push_back(id);}add[id]++;};for(int i=0;i<(int)m.size();i++){for(int f:fixed)inc(pl[m[i]*900+f]);for(int j=0;j<i;j++)inc(pl[m[i]*900+m[j]]);}int p=bp;for(int id:touch)p+=C3[K[base[id]+add[id]]]-C3[K[base[id]]];return p;}};bool disj(vector<int>const&r,vector<int>const&b){for(int i=0;i<30;i++)if(r[i]==b[i])return false;return true;}
int main(int argc,char**argv){init();string mode=argc>1?argv[1]:"rr";assert(mode=="rr"||mode=="bb");int lo=0,hiarg=-1;vector<int>r0={12,15,24,9,27,20,4,17,28,29,6,2,8,13,1,18,7,19,23,11,26,30,10,5,14,3,21,22,25,16},b0={17,10,21,22,7,15,8,28,25,13,9,4,20,26,30,12,27,24,29,23,14,1,2,11,18,6,3,16,5,19},RB={13,19,22,15},BB={8,28,13,17,19},RE,BE;for(int i=0;i<30;i++){if(find(RB.begin(),RB.end(),i)==RB.end())RE.push_back(i);if(find(BB.begin(),BB.end(),i)==BB.end())BE.push_back(i);}vector<pair<int,int>>jobs;auto&E=mode=="rr"?RE:BE;for(int a=0;a<(int)E.size();a++)for(int b=a+1;b<(int)E.size();b++)jobs.push_back({E[a],E[b]});int nl=*max_element(pl.begin(),pl.end())+1,T=5;vector<unique_ptr<W>>ws;for(int t=0;t<T;t++)ws.emplace_back(make_unique<W>(nl));atomic<int>found(0);mutex mu;vector<int>bestR,bestB;int best=3,ba=-1,bb=-1;atomic<long long>checked(0),valid(0);auto st=chrono::steady_clock::now();int hi=hiarg<0?(int)jobs.size():min(hiarg,(int)jobs.size());
#pragma omp parallel for num_threads(5) schedule(dynamic,1)
for(int z=lo;z<hi;z++){if(found.load())continue;int tid=omp_get_thread_num();auto&w=*ws[tid];auto[a,b]=jobs[z];vector<int>R=RB,B=BB;if(mode=="rr"){R.push_back(a);R.push_back(b);}else{B.push_back(a);B.push_back(b);}array<unsigned char,30>rm{},bm{};for(int x:R)rm[x]=1;for(int x:B)bm[x]=1;vector<int>fixed;for(int i=0;i<30;i++){if(!rm[i])fixed.push_back(i*30+r0[i]-1);if(!bm[i])fixed.push_back(i*30+b0[i]-1);}w.prep(fixed);vector<int>rv,bv0;for(int i:R)rv.push_back(r0[i]);for(int i:B)bv0.push_back(b0[i]);sort(rv.begin(),rv.end());long long lc=0,lv=0;int local=99;do{vector<int>r=r0;for(int k=0;k<(int)R.size();k++)r[R[k]]=rv[k];auto bv=bv0;sort(bv.begin(),bv.end());do{if(found.load())break;vector<int>bl=b0;for(int k=0;k<(int)B.size();k++)bl[B[k]]=bv[k];lc++;if(!disj(r,bl))continue;lv++;vector<int>mv;for(int x:R)mv.push_back(x*30+r[x]-1);for(int x:B)mv.push_back(x*30+bl[x]-1);int p=w.pot(mv);local=min(local,p);if(p<3){lock_guard<mutex>g(mu);if(!found.exchange(1)){best=p;bestR=r;bestB=bl;ba=a;bb=b;cerr<<"FOUND job="<<z<<" a="<<a+1<<" b="<<b+1<<" p="<<p<<"\n";}break;}}while(next_permutation(bv.begin(),bv.end()));if(found.load())break;}while(next_permutation(rv.begin(),rv.end()));checked+=lc;valid+=lv;}
auto sec=chrono::duration<double>(chrono::steady_clock::now()-st).count();if(found){cerr<<"unexpected lower state\n";return 1;}if(mode=="rr"){assert(jobs.size()==325&&checked==28080000&&valid==20353104&&best==3);}else{assert(jobs.size()==300&&checked==36288000&&valid==28146816&&best==3);}cout<<"AC p31 support closure: "<<mode<<"\n"<<"jobs: "<<jobs.size()<<"\nassignments: "<<checked<<"\nvalid: "<<valid<<"\nminimum: "<<best<<"\nseconds: "<<sec<<"\n";return 0;}
